// Package qdraccoon is the coordinator's port of the PUBLIC parts of
// packages/qd-crypto: wire formats, the round-2 commitment-opening check,
// Combine and Verify (TRaccoon Alg. 3 / QD-Wallet Algs. 4–5 with pk_j as an
// input). It never handles a key share, a seed or a chain code: everything
// here is computable from the public transcript.
//
// It mirrors the TypeScript reference line for line (same parameters, same
// two-prime NTT, same hashes) and is pinned to it by known-answer
// transcripts in testdata/, generated by packages/qd-crypto/test/rounds.test.ts.
// Research-grade and unaudited (ADR 0014, ADR 0019).
package qdraccoon

import (
	"crypto/sha3"
	"encoding/binary"
	"errors"
	"math/big"
	"math/bits"

	"github.com/ethereum/go-ethereum/crypto"
)

const (
	N      = 512
	P1     = 33292289 // 2^25 − 2^18 + 1
	P2     = 16515073 // 2^24 − 2^18 + 1
	Q      = P1 * P2  // 549 824 583 172 097
	K      = 5
	L      = 4
	Omega  = 19
	NuT    = 37
	NuW    = 40
	QT     = 4001 // ⌊q / 2^37⌉
	QW     = 500  // ⌊q / 2^40⌉
	halfQ  = (Q - 1) / 2
	seedSz = 32

	SignatureBytes = Omega*2 + L*N*7 + K*N*2 // 19 494
	PublicKeyBytes = seedSz + K*N*2          // 5 152
	Round1Bytes    = 32 + L*N*7
	Round3Bytes    = L * N * 7
	MaxParties     = 64
)

// Round2Bytes is the size of a round-2 message for an active set of size t.
func Round2Bytes(t int) int { return K*N*7 + (t-1)*33 }

// normBoundSq is ⌊B²⌋ for B = NORM_BOUND in qd-crypto params.ts (also
// QdRaccoonVerifier.NORM_BOUND_SQ).
var normBoundSq, _ = new(big.Int).SetString("392795713433239459143880802304", 10)

var (
	ErrEncoding   = errors.New("qdraccoon: malformed encoding")
	ErrTranscript = errors.New("qdraccoon: inconsistent transcript")
	ErrInvalid    = errors.New("qdraccoon: signature does not verify")
)

type Poly [N]uint64
type PolyVec []Poly

type PublicKey struct {
	SeedA [32]byte
	T     PolyVec // K polys mod q_t
}

type Challenge struct {
	Positions []int
	Negative  []bool
}

type Signature struct {
	C Challenge
	Z PolyVec // L polys mod q
	H PolyVec // K polys mod q_w
}

// ---------------------------------------------------------------------------
// Field and NTT (packages/qd-crypto/src/field.ts, ntt.ts)
// ---------------------------------------------------------------------------

type nttTables struct {
	p     uint64
	zetas [N]uint64
	nInv  uint64
}

var t1, t2 = makeTables(P1), makeTables(P2)
var p1InvModP2 = powMod(P1, P2-2, P2)

func powMod(b, e, m uint64) uint64 {
	r := uint64(1)
	b %= m
	for ; e > 0; e >>= 1 {
		if e&1 == 1 {
			r = r * b % m
		}
		b = b * b % m
	}
	return r
}

func bitReverse(i, nbits int) int {
	r := 0
	for b := 0; b < nbits; b++ {
		r |= ((i >> b) & 1) << (nbits - 1 - b)
	}
	return r
}

func makeTables(p uint64) *nttTables {
	var psi uint64
	for g := uint64(2); g < p; g++ {
		psi = powMod(g, (p-1)/(2*N), p)
		if powMod(psi, N, p) == p-1 {
			break
		}
	}
	t := &nttTables{p: p, nInv: powMod(N, p-2, p)}
	for i := 0; i < N; i++ {
		t.zetas[i] = powMod(psi, uint64(bitReverse(i, 9)), p)
	}
	return t
}

func (t *nttTables) forward(a *Poly) {
	p, k := t.p, 0
	for length := N >> 1; length > 0; length >>= 1 {
		for start := 0; start < N; start += length << 1 {
			k++
			zeta := t.zetas[k]
			for j := start; j < start+length; j++ {
				u := a[j]
				v := zeta * a[j+length] % p
				a[j] = (u + v) % p
				a[j+length] = (u + p - v) % p
			}
		}
	}
}

func (t *nttTables) inverse(a *Poly) {
	p, k := t.p, N
	for length := 1; length < N; length <<= 1 {
		for start := 0; start < N; start += length << 1 {
			k--
			zeta := p - t.zetas[k]
			for j := start; j < start+length; j++ {
				u, v := a[j], a[j+length]
				a[j] = (u + v) % p
				a[j+length] = zeta * ((u + p - v) % p) % p
			}
		}
	}
	for i := range a {
		a[i] = a[i] * t.nInv % p
	}
}

type nttPoly struct{ a, b Poly }

func toNtt(x *Poly) nttPoly {
	var r nttPoly
	for i := 0; i < N; i++ {
		r.a[i] = x[i] % P1
		r.b[i] = x[i] % P2
	}
	t1.forward(&r.a)
	t2.forward(&r.b)
	return r
}

func garner(x1, x2 uint64) uint64 {
	d := (x2 + P2 - x1%P2) % P2
	return x1 + P1*(d*p1InvModP2%P2)
}

func fromNtt(x *nttPoly) Poly {
	t1.inverse(&x.a)
	t2.inverse(&x.b)
	var out Poly
	for i := 0; i < N; i++ {
		out[i] = garner(x.a[i], x.b[i])
	}
	return out
}

func mulAcc(acc, x, y *nttPoly) {
	for i := 0; i < N; i++ {
		acc.a[i] = (acc.a[i] + x.a[i]*y.a[i]%P1) % P1
		acc.b[i] = (acc.b[i] + x.b[i]*y.b[i]%P2) % P2
	}
}

func addQ(x, y *Poly) Poly {
	var out Poly
	for i := range out {
		s := x[i] + y[i]
		if s >= Q {
			s -= Q
		}
		out[i] = s
	}
	return out
}

func subQ(x, y *Poly) Poly {
	var out Poly
	for i := range out {
		out[i] = (x[i] + Q - y[i]) % Q
	}
	return out
}

func roundPoly(x *Poly, nu uint, qNu uint64) Poly {
	var out Poly
	half := uint64(1) << (nu - 1)
	for i := range out {
		out[i] = ((x[i] + half) >> nu) % qNu
	}
	return out
}

func liftPoly(x *Poly, nu uint) Poly {
	var out Poly
	for i := range out {
		out[i] = (x[i] << nu) % Q
	}
	return out
}

// ---------------------------------------------------------------------------
// Expansion and hashing (sample.ts Xof, raccoon.ts)
// ---------------------------------------------------------------------------

type xof struct{ h *sha3.SHAKE }

func newXof(domain string, parts ...[]byte) *xof {
	h := sha3.NewSHAKE256()
	h.Write([]byte{byte(len(domain))})
	h.Write([]byte(domain))
	for _, p := range parts {
		h.Write(p)
	}
	return &xof{h: h}
}

func (x *xof) uniformPoly() Poly {
	var out Poly
	var b [7]byte
	for i := 0; i < N; {
		x.h.Read(b[:])
		v := uint64(b[0]&1)<<48 | uint64(b[1])<<40 | uint64(b[2])<<32 | uint64(b[3])<<24 |
			uint64(b[4])<<16 | uint64(b[5])<<8 | uint64(b[6])
		if v < Q {
			out[i] = v
			i++
		}
	}
	return out
}

// expandA returns A in the NTT domain. The TS reader buffers whole 7-byte
// groups, so reading the stream 7 bytes at a time is identical.
func expandA(seedA [32]byte) [K][L]nttPoly {
	var A [K][L]nttPoly
	for i := 0; i < K; i++ {
		for j := 0; j < L; j++ {
			p := newXof("QD-A", seedA[:], []byte{byte(i), byte(j)}).uniformPoly()
			A[i][j] = toNtt(&p)
		}
	}
	return A
}

func matVec(A *[K][L]nttPoly, v PolyVec) PolyVec {
	vHat := make([]nttPoly, L)
	for j := range vHat {
		vHat[j] = toNtt(&v[j])
	}
	out := make(PolyVec, K)
	for i := 0; i < K; i++ {
		var acc nttPoly
		for j := 0; j < L; j++ {
			mulAcc(&acc, &A[i][j], &vHat[j])
		}
		out[i] = fromNtt(&acc)
	}
	return out
}

func encodeU16Vec(v PolyVec) []byte {
	out := make([]byte, 0, len(v)*N*2)
	for i := range v {
		for _, c := range v[i] {
			out = append(out, byte(c>>8), byte(c))
		}
	}
	return out
}

// EncodeQVec writes each coefficient as 7 bytes big-endian (signing.ts encodeQVec).
func EncodeQVec(v PolyVec) []byte {
	out := make([]byte, 0, len(v)*N*7)
	for i := range v {
		for _, c := range v[i] {
			out = append(out, byte(c>>48), byte(c>>40), byte(c>>32), byte(c>>24), byte(c>>16), byte(c>>8), byte(c))
		}
	}
	return out
}

func EncodePublicKey(pk *PublicKey) []byte {
	return append(append([]byte{}, pk.SeedA[:]...), encodeU16Vec(pk.T)...)
}

// PublicKeyHash is keccak256("QD-VK-v1" ‖ pk), as in raccoon.ts and QdRaccoonVerifier.
func PublicKeyHash(pk *PublicKey) [32]byte {
	var h [32]byte
	copy(h[:], crypto.Keccak256([]byte("QD-VK-v1"), EncodePublicKey(pk)))
	return h
}

func challenge(vkHash []byte, msg []byte, w PolyVec) Challenge {
	seed := crypto.Keccak256([]byte("QD-Hc-v1"), vkHash, msg, encodeU16Vec(w))
	used := map[int]bool{}
	var c Challenge
	for ctr := uint32(0); len(c.Positions) < Omega; ctr++ {
		var cb [4]byte
		binary.BigEndian.PutUint32(cb[:], ctr)
		block := crypto.Keccak256(seed, cb[:])
		for i := 0; i < 32 && len(c.Positions) < Omega; i += 2 {
			v := int(block[i])<<8 | int(block[i+1])
			pos := v & (N - 1)
			if used[pos] {
				continue
			}
			used[pos] = true
			c.Positions = append(c.Positions, pos)
			c.Negative = append(c.Negative, v>>15 == 1)
		}
	}
	return c
}

func challengePoly(c *Challenge) Poly {
	var out Poly
	for i, pos := range c.Positions {
		if c.Negative[i] {
			out[pos] = Q - 1
		} else {
			out[pos] = 1
		}
	}
	return out
}

func challengeEqual(x, y *Challenge) bool {
	if len(x.Positions) != len(y.Positions) {
		return false
	}
	for i := range x.Positions {
		if x.Positions[i] != y.Positions[i] || x.Negative[i] != y.Negative[i] {
			return false
		}
	}
	return true
}

// commitmentFromResponse is ⌊A·z − 2^νt·c·t⌉_νw.
func commitmentFromResponse(pk *PublicKey, A *[K][L]nttPoly, c *Challenge, z PolyVec) PolyVec {
	Az := matVec(A, z)
	cp := challengePoly(c)
	cHat := toNtt(&cp)
	out := make(PolyVec, K)
	for i := 0; i < K; i++ {
		lt := liftPoly(&pk.T[i], NuT)
		tHat := toNtt(&lt)
		var acc nttPoly
		mulAcc(&acc, &cHat, &tHat)
		ct := fromNtt(&acc)
		d := subQ(&Az[i], &ct)
		out[i] = roundPoly(&d, NuW, QW)
	}
	return out
}

func centred(x uint64) uint64 {
	if x > halfQ {
		return Q - x
	}
	return x
}

// sqNormWithinBound reports ‖(z, 2^νw·h)‖² ≤ ⌊B²⌋, computed exactly.
func sqNormWithinBound(sig *Signature) bool {
	var hi, lo uint64
	add := func(x uint64) {
		h, l := bits.Mul64(x, x)
		var carry uint64
		lo, carry = bits.Add64(lo, l, 0)
		hi += h + carry
	}
	for _, p := range sig.Z {
		for _, c := range p {
			add(centred(c))
		}
	}
	for _, p := range sig.H {
		for _, c := range p {
			add(centred((c << NuW) % Q))
		}
	}
	sum := new(big.Int).Lsh(new(big.Int).SetUint64(hi), 64)
	sum.Or(sum, new(big.Int).SetUint64(lo))
	return sum.Cmp(normBoundSq) <= 0
}

func inRange(v PolyVec, n int, bound uint64) bool {
	if len(v) != n {
		return false
	}
	for i := range v {
		for _, c := range v[i] {
			if c >= bound {
				return false
			}
		}
	}
	return true
}

func wellFormed(pk *PublicKey, sig *Signature) bool {
	if !inRange(pk.T, K, QT) || len(sig.C.Positions) != Omega || len(sig.C.Negative) != Omega ||
		!inRange(sig.Z, L, Q) || !inRange(sig.H, K, QW) {
		return false
	}
	seen := map[int]bool{}
	for _, p := range sig.C.Positions {
		if p < 0 || p >= N || seen[p] {
			return false
		}
		seen[p] = true
	}
	return true
}

// Verify is raccoon.ts `verify`: msg must be 32 bytes.
func Verify(pk *PublicKey, msg []byte, sig *Signature) bool {
	if len(msg) != 32 || !wellFormed(pk, sig) || !sqNormWithinBound(sig) {
		return false
	}
	A := expandA(pk.SeedA)
	y := commitmentFromResponse(pk, &A, &sig.C, sig.Z)
	w := make(PolyVec, K)
	for i := range w {
		for j := 0; j < N; j++ {
			w[i][j] = (y[i][j] + sig.H[i][j]) % QW
		}
	}
	vk := PublicKeyHash(pk)
	c := challenge(vk[:], msg, w)
	return challengeEqual(&c, &sig.C)
}

// ---------------------------------------------------------------------------
// Wire formats (encoding.ts)
// ---------------------------------------------------------------------------

func readQVec(b []byte, n int) (PolyVec, error) {
	if len(b) != n*N*7 {
		return nil, ErrEncoding
	}
	v := make(PolyVec, n)
	for j := 0; j < n; j++ {
		for i := 0; i < N; i++ {
			o := 7 * (j*N + i)
			var x uint64
			for k := 0; k < 7; k++ {
				x = x<<8 | uint64(b[o+k])
			}
			if x >= Q {
				return nil, ErrEncoding
			}
			v[j][i] = x
		}
	}
	return v, nil
}

func readU16Vec(b []byte, n int, bound uint64) (PolyVec, error) {
	if len(b) != n*N*2 {
		return nil, ErrEncoding
	}
	v := make(PolyVec, n)
	for j := 0; j < n; j++ {
		for i := 0; i < N; i++ {
			x := uint64(b[2*(j*N+i)])<<8 | uint64(b[2*(j*N+i)+1])
			if x >= bound {
				return nil, ErrEncoding
			}
			v[j][i] = x
		}
	}
	return v, nil
}

func DecodePublicKey(b []byte) (*PublicKey, error) {
	if len(b) != PublicKeyBytes {
		return nil, ErrEncoding
	}
	t, err := readU16Vec(b[seedSz:], K, QT)
	if err != nil {
		return nil, err
	}
	pk := &PublicKey{T: t}
	copy(pk.SeedA[:], b[:seedSz])
	return pk, nil
}

func EncodeSignature(s *Signature) []byte {
	out := make([]byte, 0, SignatureBytes)
	for i, pos := range s.C.Positions {
		v := pos
		if s.C.Negative[i] {
			v |= 0x8000
		}
		out = append(out, byte(v>>8), byte(v))
	}
	out = append(out, EncodeQVec(s.Z)...)
	return append(out, encodeU16Vec(s.H)...)
}

func DecodeSignature(b []byte) (*Signature, error) {
	if len(b) != SignatureBytes {
		return nil, ErrEncoding
	}
	s := &Signature{}
	for i := 0; i < Omega; i++ {
		v := int(b[2*i])<<8 | int(b[2*i+1])
		if v&0x7e00 != 0 {
			return nil, ErrEncoding
		}
		s.C.Positions = append(s.C.Positions, v&(N-1))
		s.C.Negative = append(s.C.Negative, v&0x8000 != 0)
	}
	var err error
	if s.Z, err = readQVec(b[Omega*2:Omega*2+L*N*7], L); err != nil {
		return nil, err
	}
	if s.H, err = readU16Vec(b[Omega*2+L*N*7:], K, QW); err != nil {
		return nil, err
	}
	return s, nil
}

// ---------------------------------------------------------------------------
// Signing transcript (signing.ts): public checks and Combine
// ---------------------------------------------------------------------------

// Request is what all signers agreed on before round 1 (signing.ts SignRequest).
type Request struct {
	SID             [32]byte
	Act             []int // strictly increasing party indices, |Act| = T
	DerivationIndex uint32
	Msg             [32]byte
}

type Round1 struct {
	Cmt  [32]byte
	Mask PolyVec
}

type Round2 struct {
	W    PolyVec
	Tags map[int][32]byte // to → tag (opaque to the coordinator: keyed by pairwise seeds)
}

func DecodeRound1(b []byte) (*Round1, error) {
	if len(b) != Round1Bytes {
		return nil, ErrEncoding
	}
	mask, err := readQVec(b[32:], L)
	if err != nil {
		return nil, err
	}
	r := &Round1{Mask: mask}
	copy(r.Cmt[:], b[:32])
	return r, nil
}

func DecodeRound2(from int, b []byte, act []int) (*Round2, error) {
	if len(b) != Round2Bytes(len(act)) {
		return nil, ErrEncoding
	}
	w, err := readQVec(b[:K*N*7], K)
	if err != nil {
		return nil, err
	}
	r := &Round2{W: w, Tags: map[int][32]byte{}}
	o := K * N * 7
	for _, to := range act {
		if to == from {
			continue
		}
		if int(b[o]) != to {
			return nil, ErrEncoding
		}
		var tag [32]byte
		copy(tag[:], b[o+1:o+33])
		r.Tags[to] = tag
		o += 33
	}
	return r, nil
}

func DecodeRound3(b []byte) (PolyVec, error) { return readQVec(b, L) }

// ValidAct reports whether act is a strictly increasing list of t indices in [1, n].
func ValidAct(act []int, t, n int) bool {
	if len(act) != t || t < 1 || n > MaxParties {
		return false
	}
	for i, v := range act {
		if v < 1 || v > n || (i > 0 && v <= act[i-1]) {
			return false
		}
	}
	return true
}

func (r *Request) context() []byte {
	out := append([]byte{}, r.SID[:]...)
	for _, a := range r.Act {
		out = append(out, byte(a))
	}
	out = append(out, r.Msg[:]...)
	return binary.BigEndian.AppendUint32(out, r.DerivationIndex)
}

// CommitmentHash is SHA3-256("QD-cmt" ‖ sid ‖ act ‖ msg ‖ u32 index ‖ from ‖ w).
func CommitmentHash(r *Request, from int, w PolyVec) [32]byte {
	h := sha3.New256()
	h.Write([]byte("QD-cmt"))
	h.Write(r.context())
	h.Write([]byte{byte(from)})
	h.Write(EncodeQVec(w))
	var out [32]byte
	copy(out[:], h.Sum(nil))
	return out
}

// OpensCommitment reports whether a round-2 commitment share matches the
// sender's round-1 commitment (the check every signer also makes).
func OpensCommitment(r *Request, from int, r1 *Round1, w PolyVec) bool {
	h := CommitmentHash(r, from, w)
	return h == r1.Cmt
}

func sumVecs(vs []PolyVec, n int) PolyVec {
	acc := make(PolyVec, n)
	for _, v := range vs {
		for i := 0; i < n; i++ {
			acc[i] = addQ(&acc[i], &v[i])
		}
	}
	return acc
}

// Combine is signing.ts `combine`: anyone holding the transcript and pk can
// run it. Messages are in Act order. It returns ErrInvalid unless the
// combined signature verifies.
func Combine(pk *PublicKey, r *Request, r1 []*Round1, r2 []*Round2, r3 []PolyVec) (*Signature, error) {
	t := len(r.Act)
	if len(r1) != t || len(r2) != t || len(r3) != t {
		return nil, ErrTranscript
	}
	for k, from := range r.Act {
		if !OpensCommitment(r, from, r1[k], r2[k].W) {
			return nil, ErrTranscript
		}
	}
	ws := make([]PolyVec, t)
	zs := make([]PolyVec, t)
	ms := make([]PolyVec, t)
	for k := 0; k < t; k++ {
		ws[k], zs[k], ms[k] = r2[k].W, r3[k], r1[k].Mask
	}
	wSum := sumVecs(ws, K)
	w := make(PolyVec, K)
	for i := range w {
		w[i] = roundPoly(&wSum[i], NuW, QW)
	}
	zSum, mSum := sumVecs(zs, L), sumVecs(ms, L)
	z := make(PolyVec, L)
	for i := range z {
		z[i] = subQ(&zSum[i], &mSum[i])
	}
	vk := PublicKeyHash(pk)
	c := challenge(vk[:], r.Msg[:], w)
	A := expandA(pk.SeedA)
	y := commitmentFromResponse(pk, &A, &c, z)
	h := make(PolyVec, K)
	for i := range h {
		for j := 0; j < N; j++ {
			h[i][j] = (w[i][j] + QW - y[i][j]) % QW
		}
	}
	sig := &Signature{C: c, Z: z, H: h}
	if !Verify(pk, r.Msg[:], sig) {
		return nil, ErrInvalid
	}
	return sig, nil
}
